'use server';

import { revalidatePath } from 'next/cache';

let notificationsEnabled = true;

export async function toggleNotifications() {
  notificationsEnabled = !notificationsEnabled;
  revalidatePath('/');
  return { enabled: notificationsEnabled };
}

export async function getNotificationPreference() {
  return { enabled: notificationsEnabled };
}

'use client';

import { useState } from 'react';
import { toggleNotifications, getNotificationPreference } from './actions';

export default function NotificationToggle({ initialEnabled }: { initialEnabled: boolean }) {
  const [isEnabled, setIsEnabled] = useState(initialEnabled);
  const [isPending, setIsPending] = useState(false);

  const handleToggle = async () => {
    setIsPending(true);
    try {
      const result = await toggleNotifications();
      setIsEnabled(result.enabled);
    } finally {
      setIsPending(false);
    }
  };

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
      <span style={{ fontSize: '1.2rem' }}>
        {isEnabled ? '🔔' : '🔕'}
      </span>
      <button
        onClick={handleToggle}
        disabled={isPending}
        style={{
          padding: '0.5rem 1rem',
          fontSize: '1rem',
          cursor: isPending ? 'not-allowed' : 'pointer',
          opacity: isPending ? 0.6 : 1,
        }}
      >
        {isPending ? 'Updating...' : (isEnabled ? 'Disable' : 'Enable')} Notifications
      </button>
      <span style={{ color: '#666' }}>
        Status: {isEnabled ? 'On' : 'Off'}
      </span>
    </div>
  );
}

import { getNotificationPreference } from './actions';
import NotificationToggle from './NotificationToggle';

export default async function Home() {
  const { enabled } = await getNotificationPreference();

  return (
    <main style={{ padding: '2rem' }}>
      <h1>Settings</h1>
      <p>Manage your notification preferences below.</p>
      <div style={{ marginTop: '2rem' }}>
        <NotificationToggle initialEnabled={enabled} />
      </div>
    </main>
  );
}
